-- StayEase: add 74 hotels across 8 cities (target: at least 10 per city)
-- Safe to run more than once: existing hotel names/locations and related rows are preserved.
-- Run this file with stayease_db selected. Do NOT run the old migration or sample-data scripts.

USE stayease_db;

START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS tmp_stayease_hotels;
CREATE TEMPORARY TABLE tmp_stayease_hotels (
    hotel_name VARCHAR(150) NOT NULL,
    location VARCHAR(150) NOT NULL,
    description TEXT NOT NULL,
    image_url VARCHAR(500) NOT NULL,
    highlights TEXT,
    nearby_attractions TEXT,
    ideal_for VARCHAR(500),
    room_type VARCHAR(100) NOT NULL,
    total_rooms INT NOT NULL,
    price_per_night DECIMAL(10,2) NOT NULL,
    max_adults INT NOT NULL,
    max_children INT NOT NULL,
    max_occupancy INT NOT NULL,
    breakfast_lunch_price DECIMAL(10,2) NOT NULL,
    all_meals_price DECIMAL(10,2) NOT NULL,
    amenities_json JSON NOT NULL,
    PRIMARY KEY (hotel_name, location)
);

