-- 1. Insert only hotels that do not already exist.
INSERT INTO hotels (name, location, description, image_url, highlights, nearby_attractions, ideal_for)
SELECT s.hotel_name, s.location, s.description, s.image_url, s.highlights, s.nearby_attractions, s.ideal_for
FROM tmp_stayease_hotels s
WHERE NOT EXISTS (
    SELECT 1 FROM hotels h
    WHERE h.name = s.hotel_name AND h.location = s.location
);

-- 2. Add one room-inventory record per hotel, without touching existing inventory.
INSERT INTO room_inventory
(hotel_id, room_type, total_rooms, price_per_night, max_adults_per_room, max_children_per_room, max_occupancy)
SELECT h.hotel_id, s.room_type, s.total_rooms, s.price_per_night, s.max_adults, s.max_children, s.max_occupancy
FROM tmp_stayease_hotels s
JOIN hotels h ON h.name = s.hotel_name AND h.location = s.location
WHERE NOT EXISTS (
    SELECT 1 FROM room_inventory ri WHERE ri.hotel_id = h.hotel_id
);

-- 3. Add the listed amenities, skipping any that already exist for that hotel.
INSERT INTO hotel_amenities (hotel_id, amenity_name)
SELECT h.hotel_id, a.amenity_name
FROM tmp_stayease_hotels s
JOIN hotels h ON h.name = s.hotel_name AND h.location = s.location
JOIN JSON_TABLE(s.amenities_json, '$[*]' COLUMNS (amenity_name VARCHAR(100) PATH '$')) AS a
WHERE NOT EXISTS (
    SELECT 1 FROM hotel_amenities ha
    WHERE ha.hotel_id = h.hotel_id AND ha.amenity_name = a.amenity_name
);

-- 4. Add meal choices for each hotel in three separate statements.
-- Keeping one reference to the temporary table per statement avoids MySQL error 1137.
-- Breakfast Only is included at no additional charge.
INSERT INTO meal_packages
(hotel_id, package_name, includes_breakfast, includes_lunch, includes_dinner, price_per_adult_per_night, is_available)
SELECT h.hotel_id, 'Breakfast Only', 1, 0, 0, 0.00, 1
FROM tmp_stayease_hotels s
JOIN hotels h ON h.name = s.hotel_name AND h.location = s.location
WHERE NOT EXISTS (
    SELECT 1 FROM meal_packages mp
    WHERE mp.hotel_id = h.hotel_id AND mp.package_name = 'Breakfast Only'
);

INSERT INTO meal_packages
(hotel_id, package_name, includes_breakfast, includes_lunch, includes_dinner, price_per_adult_per_night, is_available)
SELECT h.hotel_id, 'Breakfast + Lunch', 1, 1, 0, s.breakfast_lunch_price, 1
FROM tmp_stayease_hotels s
JOIN hotels h ON h.name = s.hotel_name AND h.location = s.location
WHERE NOT EXISTS (
    SELECT 1 FROM meal_packages mp
    WHERE mp.hotel_id = h.hotel_id AND mp.package_name = 'Breakfast + Lunch'
);

INSERT INTO meal_packages
(hotel_id, package_name, includes_breakfast, includes_lunch, includes_dinner, price_per_adult_per_night, is_available)
SELECT h.hotel_id, 'All Meals', 1, 1, 1, s.all_meals_price, 1
FROM tmp_stayease_hotels s
JOIN hotels h ON h.name = s.hotel_name AND h.location = s.location
WHERE NOT EXISTS (
    SELECT 1 FROM meal_packages mp
    WHERE mp.hotel_id = h.hotel_id AND mp.package_name = 'All Meals'
);

COMMIT;

-- Verification: expected totals are at least 10 hotels in each of the 8 target cities.
SELECT
    CASE
        WHEN location = 'Goa' OR location LIKE '%, Goa' OR location LIKE 'Goa, %' THEN 'Goa'
        WHEN location = 'Mumbai' OR location LIKE '%, Mumbai' OR location LIKE 'Mumbai, %' THEN 'Mumbai'
        WHEN location = 'Pune' OR location LIKE '%, Pune' OR location LIKE 'Pune, %' THEN 'Pune'
        WHEN location = 'Lonavala' OR location LIKE '%, Lonavala' OR location LIKE 'Lonavala, %' THEN 'Lonavala'
        WHEN location = 'Nashik' OR location LIKE '%, Nashik' OR location LIKE 'Nashik, %' THEN 'Nashik'
        WHEN location = 'Jaipur' OR location LIKE '%, Jaipur' OR location LIKE 'Jaipur, %' THEN 'Jaipur'
        WHEN location = 'Udaipur' OR location LIKE '%, Udaipur' OR location LIKE 'Udaipur, %' THEN 'Udaipur'
        WHEN location = 'Manali' OR location LIKE '%, Manali' OR location LIKE 'Manali, %' THEN 'Manali'
        ELSE 'Other'
    END AS city,
    COUNT(*) AS hotel_count
FROM hotels
GROUP BY city
ORDER BY city;

SELECT COUNT(*) AS total_hotels FROM hotels;
SELECT COUNT(*) AS total_room_inventory_rows FROM room_inventory;
SELECT COUNT(*) AS total_amenity_rows FROM hotel_amenities;
SELECT COUNT(*) AS total_meal_package_rows FROM meal_packages;
